def compute(vars):
    useful_life = vars["v1"]
    if useful_life == 0:
        return None

    amortization_rate = 100 / useful_life

    return {
        "value": amortization_rate,
        "trace": {
            "useful_life_years": useful_life,
            "amortization_rate_percentage": amortization_rate,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
